insert into characters(slug,full_name,first_name,rank,nature_types,fighting_style,summary,biography,has_spoilers,village_id,clan_id) values ('naruto-uzumaki','Naruto Uzumaki','Naruto','Genin, later Seventh Hokage',array['Wind'],'Close-range brawling backed by clones and Rasengan','A Konoha orphan who dreams of becoming Hokage and grows from a loud outcast into the village''s leader.','{"childhood":"Grows up without a family, acting out for attention while much of the village keeps its distance.","academy":"A poor student who keeps his goal of becoming Hokage; Iruka is the teacher who first believes in him.","genin":"Placed on Team 7 with Sasuke and Sakura under Kakashi.","chunin":"Enters the Chunin Exams and shows unusual strength, though he is not promoted afterwards.","events":"Trains under Jiraiya, returns to face the Akatsuki, fights in the Fourth Great Ninja War and eventually becomes Seventh Hokage.","battles":"Defense of Konoha against Pain; the Fourth Great Ninja War; repeated clashes with Sasuke.","development":"Moves from seeking approval to protecting others, and from rivalry with Sasuke to a hard-won bond."}'::jsonb,true,(select id from villages where slug='konohagakure'),(select id from clans where slug='uzumaki'));
insert into characters(slug,full_name,first_name,rank,nature_types,fighting_style,summary,biography,has_spoilers,village_id,clan_id) values ('sasuke-uchiha','Sasuke Uchiha','Sasuke','Genin; later a wandering shinobi',array['Fire','Lightning'],'Swordsmanship and ninjutsu supported by the Sharingan','The last prominent survivor of the Uchiha clan, driven by loss and a rivalry with Naruto.','{"childhood":"Raised in the shadow of his older brother, Itachi, and wanting his father''s approval.","genin":"Joins Team 7 and develops a competitive bond with Naruto.","events":"Leaves Konoha seeking power; his later path is closely tied to the fate of the Uchiha clan.","development":"Shifts from vengeance toward taking responsibility for his choices."}'::jsonb,true,(select id from villages where slug='konohagakure'),(select id from clans where slug='uchiha'));
insert into characters(slug,full_name,first_name,rank,nature_types,fighting_style,summary,biography,has_spoilers,village_id,clan_id) values ('sakura-haruno','Sakura Haruno','Sakura','Genin to Jonin-level medic','{}','Medical ninjutsu with great physical strength','A Team 7 member who trains as a medical ninja and becomes one of Konoha''s strongest fighters.','{"genin":"Joins Team 7 alongside Naruto and Sasuke.","events":"Becomes Tsunade''s apprentice and takes part in the major battles of the war.","development":"Grows from a bystander on her team into a front-line fighter and healer."}'::jsonb,false,(select id from villages where slug='konohagakure'),null);
